    Point ap = sub(p, a);
    double t = dot(ap, ab) / dot(ab, ab);
    if (t < 0.0) t = 0.0;
    if (t > 1.0) t = 1.0;
    Point closest = add(a, mul(ab, t));
    return dist(p, closest);
