// Distance from point p to segment (a, b)
double distPointSeg(Point p, Point a, Point b) {
    Point ab = sub(b, a);
    Point ap = sub(p, a);
    if (dot(ab, ap) < 0) return norm(ap);
    Point bp = sub(p, b);
    Point ba = sub(a, b);
    if (dot(ba, bp) < 0) return norm(bp);
    double c = cross(ab, ap);
    double d = norm(ab);
    return fabs(c) / d;
}

int intersects(Point p0, Point p1, Point p2, Point p3) {
    Point d1 = sub(p1, p0);
    Point d2 = sub(p3, p2);
    double c = cross(d1, d2);
    if (fabs(c) < 1e-10) return 0;
    Point d = sub(p2, p0);
    double t = cross(d, d2) / c;
    double s = cross(d, d1) / c;
    return (t >= -1e-10 && t <= 1+1e-10 && s >= -1e-10 && s <= 1+1e-10);
}

