typedef struct {
    double x, y;
} Point;

static const double EPS = 1e-10;

double min_double(double a, double b) { return a < b ? a : b; }
double max_double(double a, double b) { return a > b ? a : b; }

Point sub(Point a, Point b) {
    Point r = {a.x - b.x, a.y - b.y};
    return r;
}

double dot(Point a, Point b) {
    return a.x * b.x + a.y * b.y;
}

double cross(Point a, Point b) {
    return a.x * b.y - a.y * b.x;
}

double norm2(Point a) {
    return dot(a, a);
}

double dist(Point a, Point b) {
    double dx = a.x - b.x;
    double dy = a.y - b.y;
    return sqrt(dx * dx + dy * dy);
}

int sgn(double x) {
    if (x > EPS) return 1;
    if (x < -EPS) return -1;
    return 0;
}

int on_segment(Point a, Point b, Point p) {
    if (sgn(cross(sub(b, a), sub(p, a))) != 0) return 0;
    return sgn(dot(sub(p, a), sub(p, b))) <= 0;
}

int segments_intersect(Point a, Point b, Point c, Point d) {
    double c1 = cross(sub(b, a), sub(c, a));
    double c2 = cross(sub(b, a), sub(d, a));
    double c3 = cross(sub(d, c), sub(a, c));
    double c4 = cross(sub(d, c), sub(b, c));

    int s1 = sgn(c1), s2 = sgn(c2), s3 = sgn(c3), s4 = sgn(c4);

    if (s1 == 0 && on_segment(a, b, c)) return 1;
    if (s2 == 0 && on_segment(a, b, d)) return 1;
    if (s3 == 0 && on_segment(c, d, a)) return 1;
    if (s4 == 0 && on_segment(c, d, b)) return 1;

    return (s1 * s2 < 0 && s3 * s4 < 0);
}

double point_to_segment_distance(Point p, Point a, Point b) {
    Point ab = sub(b, a);
    double len2 = norm2(ab);
    if (len2 < EPS) return dist(p, a);

    double t = dot(sub(p, a), ab) / len2;
    if (t < 0.0) return dist(p, a);
    if (t > 1.0) return dist(p, b);

    Point proj = {a.x + t * ab.x, a.y + t * ab.y};
    return dist(p, proj);
}

int main(void) {
    Point p0, p1, p2, p3;
    if (scanf("%lf %lf %lf %lf %lf %lf %lf %lf",
              &p0.x, &p0.y, &p1.x, &p1.y,
              &p2.x, &p2.y, &p3.x, &p3.y) != 8) {
        return 0;
    }

    if (segments_intersect(p0, p1, p2, p3)) {
        printf("0.0000000000\n");
        return 0;
    }

    double ans = point_to_segment_distance(p0, p2, p3);
    ans = min_double(ans, point_to_segment_distance(p1, p2, p3));
    ans = min_double(ans, point_to_segment_distance(p2, p0, p1));
    ans = min_double(ans, point_to_segment_distance(p3, p0, p1));

    printf("%.10f\n", ans);
