struct Point {
    double x, y, z;
    Point() : x(0), y(0), z(0) {}
    Point(double x, double y, double z) : x(x), y(y), z(z) {}
};

Point operator-(const Point& a, const Point& b) {
    return Point(a.x - b.x, a.y - b.y, a.z - b.z);
}
Point operator+(const Point& a, const Point& b) {
    return Point(a.x + b.x, a.y + b.y, a.z + b.z);
}
Point operator*(const Point& p, double t) {
    return Point(p.x * t, p.y * t, p.z * t);
}
Point operator/(const Point& p, double t) {
    return Point(p.x / t, p.y / t, p.z / t);
}
double dot(const Point& a, const Point& b) {
    return a.x * b.x + a.y * b.y + a.z * b.z;
}
Point cross(const Point& a, const Point& b) {
    return Point(a.y * b.z - a.z * b.y,
                 a.z * b.x - a.x * b.z,
                 a.x * b.y - a.y * b.x);
}
double norm(const Point& p) {
    return sqrt(p.x * p.x + p.y * p.y + p.z * p.z);
}

double segment_distance(const Point& p0, const Point& p1,
                        const Point& p2, const Point& p3) {
    Point u = p1 - p0;
    Point v = p3 - p2;
    Point w = p0 - p2;

    double a = dot(u, u);
    double b = dot(u, v);
    double c = dot(v, v);
    double d = dot(u, w);
    double e = dot(v, w);
    double denom = a * c - b * b;

    double s, t;

    if (denom < 1e-12) {
        // parallel case
        s = 0;
        t = (b > c ? d / b : e / c);
        t = max(0.0, min(1.0, t));
    } else {
        s = (b * e - c * d) / denom;
        t = (a * e - b * d) / denom;
        s = max(0.0, min(1.0, s));
        t = max(0.0, min(1.0, t));

        // check boundaries
        double s0, t0;
        double dist = 1e30;
        // try s=0
        {
            s0 = 0;
            t0 = e / c;
            t0 = max(0.0, min(1.0, t0));
            Point diff = (p0 + u * s0) - (p2 + v * t0);
            double d0 = norm(diff);
            if (d0 < dist) { dist = d0; s = s0; t = t0; }
        }
        // try s=1
        {
            s0 = 1;
            t0 = (b + e) / c;
            t0 = max(0.0, min(1.0, t0));
            Point diff = (p0 + u * s0) - (p2 + v * t0);
            double d0 = norm(diff);
            if (d0 < dist) { dist = d0; s = s0; t = t0; }
        }
        // try t=0
        {
            t0 = 0;
            s0 = -d / a;
            s0 = max(0.0, min(1.0, s0));
            Point diff = (p0 + u * s0) - (p2 + v * t0);
            double d0 = norm(diff);
            if (d0 < dist) { dist = d0; s = s0; t = t0; }
        }
        // try t=1
        {
            t0 = 1;
            s0 = (b - d) / a;
            s0 = max(0.0, min(1.0, s0));
            Point diff = (p0 + u * s0) - (p2 + v * t0);
            double d0 = norm(diff);
            if (d0 < dist) { dist = d0; s = s0; t = t0; }
        }
    }

    Point diff = (p0 + u * s) - (p2 + v * t);
    return norm(diff);
}

