const double EPS = 1e-10;

struct Point {
    double x, y;
    Point() {}
    Point(double x, double y) : x(x), y(y) {}

    Point operator + (const Point& other) const { return Point(x + other.x, y + other.y); }
    Point operator - (const Point& other) const { return Point(x - other.x, y - other.y); }
    Point operator * (double k) const { return Point(x * k, y * k); }
};

double dot(const Point& a, const Point& b) {
    return a.x * b.x + a.y * b.y;
}

double cross(const Point& a, const Point& b) {
    return a.x * b.y - a.y * b.x;
}

double norm(const Point& a) {
    return dot(a, a);
}

double absVec(const Point& a) {
    return sqrt(norm(a));
}

int ccw(Point a, Point b, Point c) {
    Point ab = b - a;
    Point ac = c - a;
    double cr = cross(ab, ac);
    if (cr > EPS) return 1;      // counter clockwise
    if (cr < -EPS) return -1;    // clockwise
    if (dot(ab, ac) < -EPS) return 2;   // c--a--b
    if (norm(ab) + EPS < norm(ac)) return -2; // a--b--c
    return 0; // on segment
}

bool intersectSS(Point a1, Point a2, Point b1, Point b2) {
    return (ccw(a1, a2, b1) * ccw(a1, a2, b2) <= 0 &&
            ccw(b1, b2, a1) * ccw(b1, b2, a2) <= 0);
}

double distancePP(Point a, Point b) {
    return absVec(a - b);
}

double distanceSP(Point a, Point b, Point p) {
    Point ab = b - a;
    Point ap = p - a;
    Point bp = p - b;

    if (dot(ab, ap) < 0.0) return absVec(ap);
    if (dot(a - b, bp) < 0.0) return absVec(bp);

    return fabs(cross(ab, ap)) / absVec(ab);
}

double distanceSS(Point a1, Point a2, Point b1, Point b2) {
    if (intersectSS(a1, a2, b1, b2)) return 0.0;
    return min({
        distanceSP(a1, a2, b1),
        distanceSP(a1, a2, b2),
        distanceSP(b1, b2, a1),
        distanceSP(b1, b2, a2)
    });
}

