        double[] r = new double[3];
        for (int i = 0; i < 3; i++) {
            d1[i] = p1[i] - p0[i];
            d2[i] = p3[i] - p2[i];
            r[i] = p0[i] - p2[i];
        }

        double a = dot(d1, d1);
        double b = dot(d1, d2);
        double c = dot(d2, d2);
        double d = dot(d1, r);
        double e = dot(d2, r);

        double denom = a * c - b * b;

        double t, u;
        if (Math.abs(denom) < 1e-12) {
            t = 0;
            u = clamp(-d / a, 0, 1);
            if (Double.isNaN(u)) u = 0;
        } else {
            t = clamp((b * e - c * d) / denom, 0, 1);
            u = clamp((b * t + e) / c, 0, 1);
            if (Double.isNaN(u)) u = 0;
            // refine t using u
            if (u >= 0 && u <= 1) {
                t = clamp((b * u - d) / a, 0, 1);
            } else {
                t = clamp((b * e - c * d) / denom, 0, 1);
                u = clamp((b * t + e) / c, 0, 1);
            }
        }

        double[] pt1 = new double[3];
        double[] pt2 = new double[3];
        for (int i = 0; i < 3; i++) {
            pt1[i] = p0[i] + t * d1[i];
            pt2[i] = p2[i] + u * d2[i];
        }

        double dist = 0;
        for (int i = 0; i < 3; i++) {
            double diff = pt1[i] - pt2[i];
            dist += diff * diff;
        }
        dist = Math.sqrt(dist);

        System.out.printf("%.10f\n", dist);
    }

    static double dot(double[] a, double[] b) {
        return a[0]*b[0] + a[1]*b[1] + a[2]*b[2];
    }

    static double clamp(double x, double lo, double hi) {
        if (x < lo) return lo;
        if (x > hi) return hi;
        return x;
    }
}

