public class Main {
    static double[] sub(double[] a, double[] b) {
        return new double[]{a[0]-b[0], a[1]-b[1]};
    }
    static double dot(double[] a, double[] b) {
        return a[0]*b[0] + a[1]*b[1];
    }
    static double cross(double[] a, double[] b) {
        return a[0]*b[1] - a[1]*b[0];
    }
    static double norm(double[] a) {
        return Math.sqrt(dot(a,a));
    }

    // distance from point p to segment (a,b)
    static double distPS(double[] p, double[] a, double[] b) {
        double[] ab = sub(b, a);
        double[] ap = sub(p, a);
        if (dot(ab, ap) < 0) return norm(ap);
        double[] bp = sub(p, b);
        if (dot(ab, bp) > 0) return norm(bp);
        // perpendicular distance
        return Math.abs(cross(ab, ap)) / norm(ab);
    }

    static boolean intersects(double[] p0, double[] p1, double[] p2, double[] p3) {
        double[] d1 = sub(p1, p0);
        double[] d2 = sub(p3, p2);
        double[] d = sub(p2, p0);
        double cross1 = cross(d1, d2);
        double t = cross(d, d2) / cross1;
        double s = cross(d, d1) / cross1;
        if (Math.abs(cross1) < 1e-10) return false;
        return t >= -1e-10 && t <= 1+1e-10 && s >= -1e-10 && s <= 1+1e-10;
    }

