public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        double nextDouble() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            double val = 0;
            while (c >= '0' && c <= '9') {
                val = val * 10 + (c - '0');
                c = read();
            }

            if (c == '.') {
                double mul = 0.1;
                c = read();
                while (c >= '0' && c <= '9') {
                    val += (c - '0') * mul;
                    mul *= 0.1;
                    c = read();
                }
            }

            return val * sign;
        }
    }

    static final double EPS = 1e-10;

    static class Point {
        double x, y;
        Point(double x, double y) {
            this.x = x;
            this.y = y;
        }
    }

    static Point sub(Point a, Point b) {
        return new Point(a.x - b.x, a.y - b.y);
    }

    static double dot(Point a, Point b) {
        return a.x * b.x + a.y * b.y;
    }

    static double cross(Point a, Point b) {
        return a.x * b.y - a.y * b.x;
    }

    static double norm2(Point a) {
        return dot(a, a);
    }

    static int sgn(double x) {
        if (x > EPS) return 1;
        if (x < -EPS) return -1;
        return 0;
    }

    static boolean onSegment(Point a, Point b, Point p) {
        return sgn(cross(sub(b, a), sub(p, a))) == 0 &&
               sgn(dot(sub(p, a), sub(p, b))) <= 0;
    }

    static int orientation(Point a, Point b, Point c) {
        return sgn(cross(sub(b, a), sub(c, a)));
    }

    static boolean segmentsIntersect(Point a, Point b, Point c, Point d) {
        int o1 = orientation(a, b, c);
        int o2 = orientation(a, b, d);
        int o3 = orientation(c, d, a);
        int o4 = orientation(c, d, b);

        if (o1 == 0 && onSegment(a, b, c)) return true;
        if (o2 == 0 && onSegment(a, b, d)) return true;
        if (o3 == 0 && onSegment(c, d, a)) return true;
        if (o4 == 0 && onSegment(c, d, b)) return true;

        return o1 * o2 < 0 && o3 * o4 < 0;
    }

    static double dist(Point a, Point b) {
        return Math.hypot(a.x - b.x, a.y - b.y);
    }

    static double pointToSegmentDistance(Point p, Point a, Point b) {
        Point ab = sub(b, a);
        Point ap = sub(p, a);
        double ab2 = norm2(ab);

        if (ab2 < EPS) return dist(p, a);

        double t = dot(ap, ab) / ab2;
        if (t < 0) return dist(p, a);
        if (t > 1) return dist(p, b);

        Point proj = new Point(a.x + ab.x * t, a.y + ab.y * t);
        return dist(p, proj);
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        Point p0 = new Point(fs.nextDouble(), fs.nextDouble());
        Point p1 = new Point(fs.nextDouble(), fs.nextDouble());
        Point p2 = new Point(fs.nextDouble(), fs.nextDouble());
        Point p3 = new Point(fs.nextDouble(), fs.nextDouble());

        double ans;
        if (segmentsIntersect(p0, p1, p2, p3)) {
            ans = 0.0;
        } else {
            ans = Math.min(
                    Math.min(pointToSegmentDistance(p0, p2, p3), pointToSegmentDistance(p1, p2, p3)),
                    Math.min(pointToSegmentDistance(p2, p0, p1), pointToSegmentDistance(p3, p0, p1))
            );
        }

        System.out.printf(Locale.US, "%.10f%n", ans);
    }
