import math

def cross(a, b):
    return a[0]*b[1] - a[1]*b[0]

def dot(a, b):
    return a[0]*b[0] + a[1]*b[1]

def subtract(a, b):
    return (a[0]-b[0], a[1]-b[1])

def add(a, b):
    return (a[0]+b[0], a[1]+b[1])

def scale(a, t):
    return (a[0]*t, a[1]*t)

def norm(a):
    return math.sqrt(a[0]**2 + a[1]**2)

def dist_point_to_point(a, b):
    return norm(subtract(a, b))

def dist_point_to_segment(p, a, b):
    ab = subtract(b, a)
    ap = subtract(p, a)
    if dot(ab, ab) < 1e-10:
        return norm(ap)
    t = dot(ap, ab) / dot(ab, ab)
    t = max(0.0, min(1.0, t))
    closest = add(a, scale(ab, t))
    return norm(subtract(p, closest))

def segments_intersect(p0, p1, p2, p3):
    d1 = subtract(p1, p0)
    d2 = subtract(p3, p2)
    d = subtract(p2, p0)

    cross_d1_d2 = cross(d1, d2)

    if abs(cross_d1_d2) < 1e-10:
        # parallel
        return False

    t = cross(d, d2) / cross_d1_d2
    s = cross(d, d1) / cross_d1_d2

    return 0 <= t <= 1 and 0 <= s <= 1

def dist_segment_to_segment(p0, p1, p2, p3):
    if segments_intersect(p0, p1, p2, p3):
        return 0.0

    d1 = dist_point_to_segment(p0, p2, p3)
    d2 = dist_point_to_segment(p1, p2, p3)
    d3 = dist_point_to_segment(p2, p0, p1)
    d4 = dist_point_to_segment(p3, p0, p1)

    return min(d1, d2, d3, d4)

