import sys
import math

EPS = 1e-10

def sub(a, b):
    return (a[0] - b[0], a[1] - b[1])

def dot(a, b):
    return a[0] * b[0] + a[1] * b[1]

def cross(a, b):
    return a[0] * b[1] - a[1] * b[0]

def norm2(a):
    return dot(a, a)

def ccw(a, b, c):
    ab = sub(b, a)
    ac = sub(c, a)
    cr = cross(ab, ac)
    if cr > EPS:
        return 1
    if cr < -EPS:
        return -1
    if dot(ab, ac) < -EPS:
        return 2
    if norm2(ab) + EPS < norm2(ac):
        return -2
    return 0

def intersect_ss(a, b, c, d):
    return ccw(a, b, c) * ccw(a, b, d) <= 0 and ccw(c, d, a) * ccw(c, d, b) <= 0

def distance_sp(a, b, p):
    ab = sub(b, a)
    ap = sub(p, a)
    bp = sub(p, b)
    if dot(ab, ap) < 0:
        return math.hypot(ap[0], ap[1])
    if dot(sub(a, b), bp) < 0:
        return math.hypot(bp[0], bp[1])
    return abs(cross(ab, ap)) / math.sqrt(norm2(ab))

def distance_ss(a, b, c, d):
    if intersect_ss(a, b, c, d):
        return 0.0
    return min(
        distance_sp(a, b, c),
        distance_sp(a, b, d),
        distance_sp(c, d, a),
        distance_sp(c, d, b),
    )

def main():
    vals = list(map(float, sys.stdin.read().split()))
    p0 = (vals[0], vals[1])
    p1 = (vals[2], vals[3])
    p2 = (vals[4], vals[5])
    p3 = (vals[6], vals[7])

    ans = distance_ss(p0, p1, p2, p3)
    print(f"{ans:.10f}")

if __name__ == "__main__":
    main()
